def _detect_line_ending(source: IO[str]) -> str:
    """Detect the first LF or CRLF line-ending style in the source stream.

    Returns the line-ending string ("\r\n" or "\n") to use for new or replaced
    assignments. Defaults to "\n" when no line ending is present. The stream
    position is restored to where it was on entry.
    """
    start = source.tell()
    try:
        content = source.read()
    except Exception:
        content = ""
    try:
        source.seek(start)
    except Exception:
        pass
    if "\r\n" in content:
        return "\r\n"
    if "\n" in content:
        return "\n"
    return "\n"


def set_key(
    dotenv_path: StrPath,
    key_to_set: str,
    value_to_set: str,
    quote_mode: str = "always",
    export: bool = False,
    encoding: Optional[str] = "utf-8",
) -> Tuple[Optional[bool], str, str]:
    """
    Adds or Updates a key/value to the given .env

    If the .env path given doesn't exist, fails instead of risking creating
    an orphan .env somewhere in the filesystem
    """
    if quote_mode not in ("always", "auto", "never"):
        raise ValueError(f"Unknown quote_mode: {quote_mode}")

    quote = (
        quote_mode == "always"
        or (quote_mode == "auto" and not value_to_set.isalnum())
    )

    if quote:
        value_out = "'{}'".format(
            value_to_set.replace("\\", "\\\\").replace("'", "\\'")
        )
    else:
        value_out = value_to_set

    with rewrite(dotenv_path, encoding=encoding) as (source, dest):
        line_ending = _detect_line_ending(source)
        if export:
            line_out = f'export {key_to_set}={value_out}{line_ending}'
        else:
            line_out = f"{key_to_set}={value_out}{line_ending}"

        replaced = False
        missing_newline = False
        for mapping in with_warn_for_invalid_lines(parse_stream(source)):
            if mapping.key == key_to_set:
                dest.write(line_out)
                replaced = True
            else:
                dest.write(mapping.original.string)
                missing_newline = not mapping.original.string.endswith("\n")
        if not replaced:
            if missing_newline:
                dest.write(line_ending)
            dest.write(line_out)

    return True, key_to_set, value_to_set

